void SetCkPnt(){// 4, 500, 30
	ofstream MkDb("miners", ios_base::binary);
	MkDb.write(reinterpret_cast<const char*>(&TrkMine.numMining), sizeof(TrkMine.numMining));
//	for(int x = 0; x < 5; x++){
		for(int y = 0; y < TrkMine.numMining; y++){
				const char* s = TrkMine.mineVec[0][y];
				int len = strlen(s);
				MkDb.write(reinterpret_cast<const char*>(&len), sizeof(len));
				MkDb.write(s, len);
		}
//	}
	MkDb.close();
	//memAsst.Astats();
}

void CIndObjs(string pName){
	for(int y = 0; y < TrkMine.numMining; y++){
		if(pName == string(TrkMine.mineVec[0][y])){
			string Opath = "AstObjs/" + pName; 
			ofstream MkObj(Opath, ios_base::binary);
		//	MkObj.write(reinterpret_cast<const char*>(&y), sizeof(y));
			for(int x = 0; x < 5; x++){
				const char* s = TrkMine.mineVec[x][y];
				int len = strlen(s);
				MkObj.write(reinterpret_cast<const char*>(&len), sizeof(len));
				MkObj.write(s, len);
			}
			MkObj.close();
			break;
		}
	}
	//memAsst.Astats();
}
// restore will have to load each obj file also
// have SetCkPnt() only save the number of products, and their names. Then, load each product's data from the
	// individual object files using that file to initialinze the list first.
void RstCkPnt(string prodN){
	ifstream RstDb("miners", ios_base::binary);
	RstDb.read(reinterpret_cast<char*>(&TrkMine.numMining), sizeof(TrkMine.numMining));
	for(int y = 0; y < TrkMine.numMining; y++){
			int len;
			RstDb.read(reinterpret_cast<char*>(&len), sizeof(len));
			RstDb.read(TrkMine.mineVec[0][y], len);
			TrkMine.mineVec[0][y][len] = '\0';
	}
	RstDb.close();
	if(prodN == "a"){
		for(int q = 0; q < TrkMine.numMining; q++){
			string loadProd = "AstObjs/" + string(TrkMine.mineVec[0][q]);
			ifstream RstObj(loadProd, ios_base::binary);
//			int objIndex;
//			RstObj.read(reinterpret_cast<char*>(&objIndex), sizeof(objIndex));
			for(int z = 0; z < 5; z++){
				int len2;
				RstObj.read(reinterpret_cast<char*>(&len2), sizeof(len2));
				RstObj.read(TrkMine.mineVec[z][q], len2);
				TrkMine.mineVec[z][q][len2] = '\0';
			}
			RstObj.close();
			memAsst.Astats();
		}
	}else{
		for(int j = 0; j < TrkMine.numMining; j++){
			if(prodN == string(TrkMine.mineVec[0][j])){
				string loadProd = "AstObjs/" + prodN;
				ifstream RstObj(loadProd, ios_base::binary);
				for(int z = 0; z < 5; z++){
					int len2;
					RstObj.read(reinterpret_cast<char*>(&len2), sizeof(len2));
					RstObj.read(TrkMine.mineVec[z][j], len2);
					TrkMine.mineVec[z][j][len2] = '\0';
				}
				RstObj.close();
				break;
			}
		}
	}
	//memAsst.Astats();
}

void RstCkPntI(){
	ifstream RstI("miners", ios_base::binary);
	RstI.read(reinterpret_cast<char*>(&TrkMine.numMining), sizeof(TrkMine.numMining));
	for(int b = 0; b < 5; b++){
		for(int y = 0; y < TrkMine.numMining; y++){
			int len;
			RstI.read(reinterpret_cast<char*>(&len), sizeof(len));
			RstI.read(TrkMine.mineVec[b][y], len);
			TrkMine.mineVec[b][y][len] = '\0';
			cout << TrkMine.mineVec[b][y] << endl;
		}
	}
	RstI.close();
	for(int o = 0; o < 5; o++){
		cout << TrkMine.mineVec[o][0] << endl;
	}
	memAsst.Astats();
}

void LaunchM(){
	char chLaunch = ' ';
	do{
		cout << "Enter 'z' for command line, 's' to set number of miners, 'x' to launch all miners, 'y' to set all miners,\n" << 
				"'a' to add a miner, 'q' to launch a selected miner, or 'w' to reset selected miners: ";
		cin >> chLaunch;
		if(chLaunch == 's'){
			cout << "Enter number of miners: ";
			cin >> TrkMine.numMining;
		}else if(chLaunch == 'q'){
			string mName;
			cout << "Enter miner name: ";
			cin >> mName;
			for(int z = 0; z < 500; z++){
				if(mName == string(TrkMine.mineVec[0][z])){
					memAsst.MineTarg(TrkMine.mineVec[0][z], 'd');
				}
			}
		}else if(chLaunch == 'a'){
			do{
				for(int n = 0; n < 500; n++){
					if(TrkMine.mineVec[0][n][0] == '\0'){
						cout << "Enter miner target (name, buy price, sell price, amount purchased, and starting price): ";
						cin >> TrkMine.mineVec[0][n];
						cin >> TrkMine.mineVec[1][n];
						cin >> TrkMine.mineVec[2][n];
						cin >> TrkMine.mineVec[3][n];
						cin >> TrkMine.mineVec[4][n];
						++TrkMine.numMining;
						SetCkPnt();
						CIndObjs(string(TrkMine.mineVec[0][n]));
						cout << "Launch miner now? (g - yes/h - no): ";
						cin >> chLaunch;
						if(chLaunch == 'g'){
							memAsst.MineTarg(TrkMine.mineVec[0][n], 'd');
							break;
						}else if(chLaunch == 'h'){
							break;
						}
					}
				}
				cout << "Add another miner? (i - yes/n - no): ";
				cin >> chLaunch;
			}while(chLaunch != 'n');
		}else if(chLaunch == 'w'){
			for(int z = 0; z < 500; z++){
				if(TrkMine.mineVec[0][z][0] != '\0'){
					cout << "Miner " << z << ": " << TrkMine.mineVec[0][z] << ", reset? (y/n) Delete? (q):\n";
					for(int y = 1; y < 5; y++){
						cout << TrkMine.mineVec[y][z] << endl;
					}
					cin >> chLaunch;
					if(chLaunch == 'q'){
						string remObj = "rm AstObjs/" + string(TrkMine.mineVec[0][z]);
						system(remObj.c_str());
						for(int d = 0; d < 5; d++){
							for(int f = 0; f < 30; f++){
								TrkMine.mineVec[d][z][f] = '\0';
							}
						}
						for(int d = (z + 1); d < TrkMine.numMining; d++){
							for(int h = 0; h < 5; h++){
								strcpy(TrkMine.mineVec[h][d - 1], TrkMine.mineVec[h][d]);
							}
						}
						--TrkMine.numMining;
					}else if(chLaunch == 'y'){
						cout << "Enter miner data: (name, buy price, sell price, amount purchased, and starting price): ";
						for(int k = 0; k < 5; k++){
							cin >> TrkMine.mineVec[k][z];
						}
//						++TrkMine.numMining;
						CIndObjs(string(TrkMine.mineVec[0][z]));
					}else if(chLaunch == 'n'){
						continue;
					}
				}else{
					continue;
				}
			}
		}else if(chLaunch == 'x'){
			for(int z = 0; z < TrkMine.numMining; z++){
			//	for(int y = 0; y < memAsst.countAsts; y++){
			//		if(string(TrkMine.mineVec[0][z]) == string(memAsst.asttup[0][4][y])){
						memAsst.MineTarg(TrkMine.mineVec[0][z], 'd');
			//		}
				}
		}else if(chLaunch == 'y'){
			cout << "Enter number of miners: ";
				cin >>TrkMine.numMining;
			for(int z = 0; z < TrkMine.numMining; z++){
				cout << "Enter product, and amount purchased: ";
				cin >> TrkMine.mineVec[0][z] >> TrkMine.mineVec[3][z]; // 294
			}
			memAsst.BldStrct('b');
			for(int l = 0; l < TrkMine.numMining; l++){
				for(int k = 0; k < memAsst.countAsts; k++){
					if(string(TrkMine.mineVec[0][l]) == string(memAsst.asttup[0][4][k])){
						double curPri = stod(memAsst.asttup[2][2][k]); //.02
						double curAmt = stod(memAsst.asttup[1][0][k]); // 212
						curAmt = curAmt / stod(TrkMine.mineVec[3][l]); // .721088

						
						curAmt = 1 - curAmt; // set curAmt to % down 
						curPri = (1 + curAmt) * curPri; // starting price
						snprintf(TrkMine.mineVec[4][l], 29, "%.8f", curPri);
						curPri = curPri * 0.90;
						snprintf(TrkMine.mineVec[1][l], 29, "%.8f", curPri);
						curPri = (curPri / 0.90) * 1.03;
						snprintf(TrkMine.mineVec[2][l], 29, "%.8f", curPri);
					}
				}
				CIndObjs(string(TrkMine.mineVec[0][l]));
			}

			/*cout << "Enter miner targets: (name, buy price, sell price, amount purchased, and starting price)";
			for(int i = 0; i < TrkMine.numMining; i++){
				cin >> TrkMine.mineVec[0][i];
				cin >> TrkMine.mineVec[1][i];
				cin >> TrkMine.mineVec[2][i];
				cin >> TrkMine.mineVec[3][i];
				cin >> TrkMine.mineVec[4][i];
				memAsst.MineTarg(TrkMine.mineVec[0][i], 'd');	
			}*/
			for(int i = TrkMine.numMining; i < 500; i++){
				for(int l = 0; l < 5; l++){
					for(int k = 0; k < 30; k++){
						TrkMine.mineVec[l][i][k] = '\0';
					}
				}
			}
		}
			SetCkPnt();
	}while(chLaunch != 'z');
}

